'use strict';

/**
* Return a boolean indicating if the sign bit is on (true) or off (false).
*
* @module @stdlib/number/int32/base/signbit
*
* @example
* var signbit32 = require( '@stdlib/number/int32/base/signbit' );
*
* var bool = signbit32( 4 );
* // returns false
*
* var bool = signbit32( -4 );
* // returns true
*
* var bool = signbit32( 0 );
* // returns false
*
* var bool = signbit32( -0 );
* // returns false
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
